import {applyBlocking} from "./blocking.js";

// Pairing is explicit. The extension is inert until the owner supplies a token
// generated by `jarvis veil pair`; no browsing data leaves loopback JARVIS.
chrome.runtime.onMessage.addListener((report) => {
  if (!report || report.kind !== "veil-report") return;
  chrome.storage.local.get(["pairToken", "endpoint"], async ({ pairToken, endpoint }) => {
    if (!pairToken) return;
    const target = endpoint || "http://127.0.0.1:8787/api/veil/events";
    try {
      await fetch(target, {method: "POST", headers: {
        "Content-Type": "application/json", "X-JARVIS-Veil-Token": pairToken
      }, body: JSON.stringify(report.payload), cache: "no-store", credentials: "omit"});
    } catch (_) { /* JARVIS may be offline; do not queue browsing history. */ }
  });
});

// Blocking is off until the owner turns it on in the options page. The saved
// choice is re-applied on start so the browser's ruleset state cannot drift
// from what the options page shows.
const restore = () => chrome.storage.local.get(["blocking"], ({blocking}) =>
  applyBlocking(chrome, blocking || {}).catch(() => {}));
chrome.runtime.onStartup.addListener(restore);
chrome.runtime.onInstalled.addListener(restore);
// One click on the toolbar button reaches the off switch.
chrome.action.onClicked.addListener(() => chrome.runtime.openOptionsPage());
